(()=>{
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const draftNotes=new Map();let generation=0;window.addEventListener('beforeunload',e=>{if(draftNotes.size){e.preventDefault();e.returnValue=''}});
window.renderDiscussion=async(q,showDiscussion)=>{
 const n=++generation,box=document.getElementById('discussion');
 const key='note:'+q.id;let note=Account.get(key,''),storageOK=true;
 box.innerHTML=`<h3>Private study note</h3><p>Saved to your account. Not shown in public discussion or the admin feedback inbox.</p><textarea id="private-note" rows="4" maxlength="20000" aria-label="Private study note">${esc(note)}</textarea><p id="note-state" role="status">${storageOK?'':'Browser storage is unavailable; notes cannot be saved.'}</p><h3>Send feedback to admin</h3><p>Use this to flag a disputed answer or suggest a correction. This message is not shown in public discussion.</p><textarea id="admin-message" rows="3" maxlength="5000" aria-label="Feedback to admin"></textarea><button type="button" id="send-admin" class="secondary">Send to admin</button><p id="admin-state" role="status"></p><div id="my-feedback"></div>${showDiscussion&&q.discussion_enabled?'<h3>Public discussion</h3><p>Comments are visible to everyone using this question bank.</p><div id="public-comments"></div><textarea id="public-message" rows="3" maxlength="5000" aria-label="Public comment"></textarea><button type="button" id="send-public" class="secondary">Post comment</button><p id="public-state" role="status"></p>':showDiscussion?'<p>Public discussion is closed for this question.</p>':'<p>Public discussion is available after submitting the exam, when enabled by the admin.</p>'}`;
 // Keep optional tools collapsed and preserve note drafts across question renders.
 const headings=[...box.querySelectorAll('h3')];
 for(const heading of headings){const details=document.createElement('details');details.className='optional-panel';const summary=document.createElement('summary');summary.textContent=heading.textContent;details.append(summary);let node=heading.nextSibling;while(node&&node.nodeName!=='H3'){const next=node.nextSibling;details.append(node);node=next}heading.replaceWith(details);}
 const $=id=>document.getElementById(id);
 $('private-note').oninput=e=>{draftNotes.set(q.id,e.target.value)};
 const saveNote=document.createElement('button');saveNote.className='secondary';saveNote.textContent='Save private note';$('private-note').after(saveNote);
 if(draftNotes.has(q.id))$('private-note').value=draftNotes.get(q.id);
 saveNote.onclick=async()=>{const field=$('private-note'),status=$('note-state');saveNote.disabled=true;try{await Account.save(key,field.value);draftNotes.delete(q.id);status.textContent='Saved to your account.'}catch(e){status.textContent=e.message}finally{saveNote.disabled=false}};

 async function loadMine(){try{const items=await Account.request('/api/my-feedback?question='+encodeURIComponent(q.id));if(n!==generation)return;$('my-feedback').innerHTML='<h4>Your feedback and decisions</h4>'+items.filter(x=>x.kind==='admin').map(x=>`<article><p style="white-space:pre-wrap">${esc(x.body)}</p><strong>${esc(x.status)}</strong>${x.decision?`<p style="white-space:pre-wrap">Admin decision: ${esc(x.decision)}</p>`:''}</article>`).join('')}catch(e){if(n===generation)$('my-feedback').textContent='Could not load your feedback.'}}
 async function load(){try{const r=await fetch('/api/feedback?question='+encodeURIComponent(q.id));if(!r.ok)throw Error();const items=await r.json();if(n!==generation)return;$('public-comments').innerHTML=items.map(x=>`<article><small>${esc(x.author||'Earlier local comment')} · ${esc(x.created)}</small><p style="white-space:pre-wrap">${esc(x.body)}</p><strong>${esc(x.status)}</strong>${x.decision?`<p style="white-space:pre-wrap">Admin decision: ${esc(x.decision)}</p>`:''}</article>`).join('')||'<p>No comments yet.</p>'}catch{if(n===generation&&$('public-comments'))$('public-comments').textContent='Could not load comments.'}}
 for(const kind of ['admin','public']){const button=$('send-'+kind);if(!button)continue;button.onclick=async()=>{const field=$(kind+'-message'),status=$(kind+'-state');if(!field.value.trim()){status.textContent='Enter a message first.';return}button.disabled=true;try{const r=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json','X-Quiz-Admin':'1'},body:JSON.stringify({question_id:q.id,kind,body:field.value})});const data=await r.json();if(!r.ok)throw Error(data.error);field.value='';status.textContent=kind==='admin'?'Sent to admin.':'Comment posted.';if(kind==='public')await load();else await loadMine()}catch(e){status.textContent=e.message||'Could not send. Try again.'}finally{button.disabled=false}}}
 await loadMine();if(showDiscussion&&q.discussion_enabled)await load();
};
})();
